package com.projecteden.collection.controller;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import com.projecteden.collection.dto.CollectionSummaryResponse;import com.projecteden.collection.service.CollectionService;import com.projecteden.user.domain.User;@RestController@RequestMapping("/api/collections")public class CollectionController{private final CollectionService service;public CollectionController(CollectionService service){this.service=service;}@GetMapping("/me")public CollectionSummaryResponse get(@AuthenticationPrincipal User user){return service.getMyCollectionSummary(user.getId());}}
